CREATE TABLE "user" (id text PRIMARY KEY,name text NOT NULL,email text NOT NULL UNIQUE,email_verified boolean NOT NULL DEFAULT false,image text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE session (id text PRIMARY KEY,expires_at timestamptz NOT NULL,token text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),ip_address text,user_agent text,user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE);
CREATE INDEX session_user_idx ON session(user_id);
CREATE TABLE account (id text PRIMARY KEY,account_id text NOT NULL,provider_id text NOT NULL,user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,access_token text,refresh_token text,id_token text,access_token_expires_at timestamptz,refresh_token_expires_at timestamptz,scope text,password text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(provider_id,account_id));
CREATE TABLE verification (id text PRIMARY KEY,identifier text NOT NULL,value text NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rate_limit (id text PRIMARY KEY,key text NOT NULL UNIQUE,count integer NOT NULL,last_request bigint NOT NULL);
CREATE TABLE employee (id uuid PRIMARY KEY,user_id text NOT NULL UNIQUE REFERENCES "user"(id),role text NOT NULL CHECK(role IN ('admin','employee')),active boolean NOT NULL DEFAULT true);
CREATE TABLE bootstrap_state (id integer PRIMARY KEY CHECK(id=1),completed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_event (id uuid PRIMARY KEY,actor_user_id text NOT NULL REFERENCES "user"(id),request_id text NOT NULL,action text NOT NULL,entity_id text NOT NULL,reason text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE document (id uuid PRIMARY KEY,employee_id uuid NOT NULL REFERENCES employee(id),kind text NOT NULL CHECK(kind IN ('payslip','receipt')),title text NOT NULL);
CREATE TABLE draft_intent (id uuid PRIMARY KEY,company_id uuid NOT NULL,salary_month text NOT NULL CHECK(salary_month ~ '^[0-9]{4}-[0-9]{2}$'),job_kind text NOT NULL CHECK(job_kind='draft'),due_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','held')),UNIQUE(company_id,salary_month,job_kind));
